          {/capture}
          {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '0', 'Class' => 'min-w-40 flex-1'], 'children' => $c_4])|noescape}
          {=ui_include('blocks/number-field.latte', ['p' => ['value' => ui_str(ui_get($v_line, ['qty'])), 'name' => ui_tpl('{0}-qty-{1}', [$v_id, ui_get($v_line, ['id'])]), 'min' => '1', 'label' => ui_get($v_labels, ['qty']), 'decrease' => ui_get($v_labels, ['decrease']), 'increase' => ui_get($v_labels, ['increase'])]])|noescape}
          {capture $c_5}
            {=ui_text(ui_money(ui_mul(ui_get($v_line, ['price']), ui_get($v_line, ['qty'])), ui_get($v_line, ['currency'])))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'base', 'Weight' => 'bold', 'Class' => 'w-24 text-right'], 'children' => $c_5])|noescape}
          {capture $c_6}
            {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'trash', 'Size' => 16]])|noescape}
          {/capture}
