          {=ui_text(ui_get($v_actions, ['back']))}
        {/capture}
        {=ui_include('ui/button/button.latte', ['p' => ['Variant' => 'outline', 'Size' => 'default'], 'children' => $c_8])|noescape}
        {capture $c_9}
