        {/capture}
        {=ui_include('ui/button/button.latte', ['p' => ['Variant' => 'ghost', 'Size' => 'default'], 'children' => $c_9])|noescape}
      {/capture}
      {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Justify' => 'between', 'Class' => 'flex-wrap'], 'children' => $c_10])|noescape}
    {/capture}
    {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Align' => 'stretch', 'Class' => ui_s((ui_t(ui_eq($v_layout, 'split')) ? 'lg:col-span-2' : '')), 'Attrs' => ui_attrs(['data-testid', 'lines'])], 'children' => $c_11])|noescape}
    {capture $c_12}
      {=ui_include('blocks/cart-summary-card.latte', ['p' => ['field' => ui_tpl('{0}-promo', [$v_id]), 'lines' => $v_lines, 'rows' => $v_rows, 'promos' => $v_promos, 'labels' => $v_totals, 'promo' => $v_promo, 'progress' => $v_progress]])|noescape}
    {/capture}
    {=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s((ui_t(ui_eq($v_layout, 'split')) ? 'lg:sticky lg:top-8' : '')), 'Attrs' => ui_attrs(['data-testid', 'aside'])], 'children' => $c_12])|noescape}
  {/capture}
  {=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s((ui_t(ui_eq($v_layout, 'split')) ? 'grid grid-cols-1 items-start gap-8 lg:grid-cols-3' : 'grid grid-cols-1 gap-8'))], 'children' => $c_13])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_14])|noescape}
